from bisect import bisect_left

def length_of_lis(nums):
    tails = []                         # tails[k]: smallest tail of a length-k+1 run
    for x in nums:
        i = bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)            # extends the longest run
        else:
            tails[i] = x               # a smaller tail for length i+1
    return len(tails)

