def length_of_lis(nums):
    dp = [1] * len(nums)               # dp[i]: longest run ending at i
    for i in range(len(nums)):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)
